from __future__ import annotations

import os
import tomllib
from typing import Any


class ConfigError(Exception):
    def __init__(self, key: str, expected: str, actual: str | None = None):
        self.key = key
        self.expected = expected
        self.actual = actual
        msg = f"{key}: expected {expected}"
        if actual is not None:
            msg += f", got {actual!r}"
        super().__init__(msg)


def flatten_cfg(d: dict[str, Any], prefix: str = "") -> dict[str, Any]:
    result: dict[str, Any] = {}
    for k, v in d.items():
        key = f"{prefix}{k}" if prefix else k
        if isinstance(v, dict):
            result.update(flatten_cfg(v, f"{key}__"))
        else:
            result[key] = v
    return result


def coerce(value: str, expected_type: type) -> Any:
    if expected_type is int:
        try:
            return int(value)
        except ValueError:
            raise ConfigError("unknown", "int", value)
    if expected_type is float:
        try:
            return float(value)
        except ValueError:
            raise ConfigError("unknown", "float", value)
    if expected_type is bool:
        if value.lower() in ("true", "yes", "1"):
            return True
        if value.lower() in ("false", "no", "0"):
            return False
        raise ConfigError("unknown", "bool", value)
    if expected_type is str:
        return value
    raise ConfigError("unknown", str(expected_type), value)


def load_toml(path: str | None) -> dict[str, Any] | None:
    if path is None:
        return None
    try:
        with open(path, "rb") as f:
            return flatten_cfg(tomllib.load(f))
    except FileNotFoundError:
        return None


